    {
      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória gerenciada no método Update() decorrente de concatenação iterativa de strings ('s += i.ToString()') e alocações repetidas de arrays de objetos. Strings em C# são imutáveis, gerando novos objetos na heap a cada iteração e acionando coletas frequentes e demoradas do Garbage Collector (GC.Collect atingindo ~25.8ms).",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _cachedStringBuilder;
        private MaterialPropertyBlock _propertyBlock;
        private static readonly int BaseColorPropertyId = Shader.PropertyToID("_BaseColor");

        private void Awake()
        {
            _cachedStringBuilder = new StringBuilder(4096);
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;

            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _cachedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _cachedStringBuilder.Append(i);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor(BaseColorPropertyId, UnityEngine.Random.ColorHSV());
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, toda vez que você junta textos usando '+' ou chama '.ToString()', um novo pedaço de memória gerenciada é criado e o anterior é jogado fora. Em uma cena rodando a 60 quadros por segundo, fazer isso centenas ou milhares de vezes por frame cria gigabytes de lixo virtual. O Garbage Collector precisa congelar o jogo para limpar essa sujeira, causando travamentos visíveis (engasgos). Substituímos a concatenação contínua por StringBuilder reutilizável e removemos alocações vazias e scans desnecessários no Update."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Chamada repetitiva de 'GameObject.FindObjectsOfType<GameObject>()' em todos os quadros dentro de um loop de Update(). Esta operação varre toda a árvore de objetos da cena nativa e converte para instâncias gerenciadas, gerando sobrecarga massiva na CPU (até 102ms/frame) e alocando arrays que sobrecarregam o Garbage Collector.",
      "codigo_refatorado": "// A varredura contínua foi totalmente eliminada do Update(). Para arquiteturas funcionais que precisam de referências a múltiplos objetos, utilize registro no Awake/OnEnable através de coleções estáticas ou Singletons de serviço:
/*
public static readonly HashSet<GameObject> ActiveObjects = new HashSet<GameObject>();
private void OnEnable() => ActiveObjects.Add(gameObject);
private void OnDisable() => ActiveObjects.Remove(gameObject);
*/",
      "explicacao_didatica": "Métodos de busca como 'FindObjectsOfType' vasculham todos os objetos existentes na memória da fase inteira, um por um. Fazer isso a cada frame é equivalente a ler uma enciclopédia inteira toda vez que você pisca os olhos. A melhor abordagem é manter uma lista prévia com os objetos necessários ou registrá-los no momento em que forem criados."
    }
  ],
  "dicas_level_design": null
}

